mapper.select:
select account_id, phone_mask, status, latest_consent_status, created_at, deleted_at
from accounts
where account_id = #{accountId}

select session_id, installation_id, status, created_at, revoked_at
from account_sessions
where account_id = #{accountId}
order by created_at desc, session_id desc
limit #{limit}

select audit_id, session_id, installation_id, action, result, reason, created_at
from consent_audit_logs
where account_id = #{accountId}
order by created_at desc, audit_id desc
limit #{limit}

mapper.update:
update account_sessions
set status = #{newStatus},
    revoked_at = #{changedAt}
where account_id = #{accountId}
  and status != #{newStatus}
